return items.map(item => {
  const data = item.json;

  const likes = Number(data.likes) || 0;
  const comments = Number(data.comments) || 0;
  const rawViews = data.views;

  const views =
    rawViews !== null &&
    rawViews !== undefined &&
    rawViews !== "" &&
    Number(rawViews) > 0
      ? Number(rawViews)
      : null;

  const engagement = likes + comments;

  const engagementRate =
    views !== null
      ? Number(((engagement / views) * 100).toFixed(2))
      : null;

  return {
    json: {
      ...data,

      likes,
      comments,
      views,

      engagement,

      engagement_rate: engagementRate,

      engagement_rate_available: engagementRate !== null
    }
  };
});

const raw = items[0].json.text;

let audit;

try {
  audit = JSON.parse(raw);
} catch (error) {
  throw new Error("AI did not return valid JSON");
}

return [
  {
    json: audit
  }
];

return items.map(item => {
  const post = item.json;

  return {
    json: {
      username: post.ownerUsername || post.username || "",
      post_type: post.type || "",
      caption: post.caption || "",
      likes: post.likesCount || 0,
      comments: post.commentsCount || 0,
      views: post.videoViewCount || post.videoPlayCount || 0,
      hashtags: post.hashtags || [],
      posted_at: post.timestamp || "",
      shortcode: post.shortCode || "",
      url: post.url || ""
    }
  };
});

const posts = items.map(item => item.json);

posts.sort((a, b) => {
  return (b.engagement_rate || 0) - (a.engagement_rate || 0);
});

return posts.map((post, index) => ({
  json: {
    ...post,
    performance_rank: index + 1
  }
}));

const posts = items.map(item => item.json);

const totalPosts = posts.length;

const totalLikes = posts.reduce((sum, post) => sum + (post.likes || 0), 0);

const totalComments = posts.reduce(
  (sum, post) => sum + (post.comments || 0),
  0
);

const totalViews = posts.reduce(
  (sum, post) => sum + (post.views || 0),
  0
);

const averageEngagementRate =
  posts.reduce(
    (sum, post) => sum + (post.engagement_rate || 0),
    0
  ) / totalPosts;

return [
  {
    json: {
      total_posts: totalPosts,
      total_likes: totalLikes,
      total_comments: totalComments,
      total_views: totalViews,
      average_engagement_rate: Number(
        averageEngagementRate.toFixed(2)
      ),
      posts: posts
    }
  }
];

const audit = items[0].json;

return [
  {
    json: {
      success: true,

      summary: {
        evidence_strength:
          audit.overall_performance?.evidence_strength || "",
        overall_performance:
          audit.overall_performance?.summary || ""
      },

      top_performers: audit.top_performers || [],

      underperformers: audit.underperformers || [],

      content_patterns:
        audit.content_patterns || [],

      caption_insights:
        audit.caption_insights || [],

      hashtag_insights:
        audit.hashtag_insights || [],

      engagement_patterns:
        audit.engagement_patterns || [],

      recommendations:
        audit.recommendations || [],

      data_quality_issues:
        audit.data_quality_issues || [],

      limitations:
        audit.limitations || []
    }
  }
];

const posts = items.map(item => item.json);

// ----------------------------------
// 1. Calculate basic metrics
// ----------------------------------

const processed = posts.map(post => {

  const likes = Number(post.likes) || 0;
  const comments = Number(post.comments) || 0;

  const rawViews = post.views;

  const views =
    rawViews !== null &&
    rawViews !== undefined &&
    rawViews !== "" &&
    Number(rawViews) > 0
      ? Number(rawViews)
      : null;

  const engagement = likes + comments;

  const engagementRate =
    views !== null
      ? Number(((engagement / views) * 100).toFixed(2))
      : null;

  return {
    ...post,

    likes,
    comments,
    views,
    engagement,

    engagement_rate: engagementRate,

    engagement_rate_available:
      engagementRate !== null
  };
});


// ----------------------------------
// 2. Get valid engagement rates
// ----------------------------------

const validRates = processed
  .filter(post => post.engagement_rate !== null)
  .map(post => post.engagement_rate)
  .sort((a, b) => a - b);


// ----------------------------------
// 3. Calculate percentile
// ----------------------------------

function percentile(value, values) {

  if (!values.length) {
    return null;
  }

  const belowOrEqual = values.filter(
    v => v <= value
  ).length;

  return Number(
    ((belowOrEqual / values.length) * 100).toFixed(1)
  );
}


// ----------------------------------
// 4. Add performance score
// ----------------------------------

const finalPosts = processed.map(post => {

  let performanceScore = null;
  let performancePercentile = null;

  if (post.engagement_rate !== null) {

    performancePercentile =
      percentile(
        post.engagement_rate,
        validRates
      );

    /*
      Convert percentile into a 0–100 score.

      0   = weakest
      50  = around median
      100 = strongest
    */

    performanceScore =
      Math.round(performancePercentile);
  }

  return {
    ...post,

    performance_score:
      performanceScore,

    performance_percentile:
      performancePercentile
  };
});


// ----------------------------------
// 5. Return original post structure
// ----------------------------------

return finalPosts.map(post => ({
  json: post
}));
